ALTER TABLE public.sre_pacote_content
  ADD COLUMN IF NOT EXISTS tipo text NOT NULL DEFAULT 'generico' CHECK (tipo IN ('generico','especifico')),
  ADD COLUMN IF NOT EXISTS detalhes_adicionais text,
  ADD COLUMN IF NOT EXISTS restricoes text,
  ADD COLUMN IF NOT EXISTS premissas text,
  ADD COLUMN IF NOT EXISTS fora_escopo text;

INSERT INTO public.sre_params (key,label,value,tipo,status,descricao,ordem) VALUES
('proposta_generico_titulo','Pacote genérico — título', to_jsonb('Serviços profissionais consultivos para Zabbix ({horas} horas) – Pacote pré-pago'::text),'text','confirmado','{horas} é trocado pelas horas do pacote',300),
('proposta_generico_descricao','Pacote genérico — descrição', to_jsonb('Recurso técnico certificado com títulos de certificação oficial Zabbix alocado em períodos específicos em formato remoto para execução de tarefas por prazo determinado em temas relacionados à monitoramento. As horas destinadas para “Serviços profissionais consultivos para Zabbix” são pacotes pré-pagos e podem ser consumidos em períodos no máximo anuais. Descrição do serviço conforme o fabricante: https://www.zabbix.com/br/consulting'::text),'text','confirmado','{horas} é trocado pelas horas do pacote',310),
('proposta_generico_fora_escopo','Pacote genérico — fora do escopo', to_jsonb(E'Execução de quantidade de horas adicional ao contratado;\nNecessidade de recursos adicionais com habilidades distintas das acordadas;\nParametrizações necessárias em hosts de rede para viabilizar a coleta de dados através de protocolos de monitoramento e suas devidas permissões e credenciais;\nPrestar Serviço de suporte a aplicações específicas;\nInterações ou gerenciamento de soluções de monitoramento que não sejam Zabbix;\nInterações ou configurações de infraestrutura física de servidores, networking, storage e demais tecnologias que podem estar presentes no ambiente da contratante;\nSuporte para desenvolvimentos, integrações e outros artefatos que sejam entregues de acordo com o que foi demandado pela contratante. Este tipo de suporte, caso necessário, deverá ser tema de nova proposta comercial, específica para o desenvolvimento entregue;\nInterações fora do horário comercial.'::text),'text','confirmado','Um item por linha',320),
('proposta_generico_restricoes','Pacote genérico — restrições', to_jsonb(E'Tempo de alocações contratadas;\nEste serviço não é suporte de ambiente Zabbix, ele não possui atendimento de incidentes provenientes da disponibilidade e desempenho da aplicação. Todas as atividades que serão conduzidas através deste serviço são agendadas e encaixadas em sprints de trabalho;\nEste serviço não é garantia de conclusão, atingimento de resultados ou entregas específicas do escopo acordado, pois é conduzido conforme o tempo de alocação, e não, com alocação que garanta a execução completa dos serviços independente da variedade e dimensão do ambiente de monitoramento Zabbix;\nNo caso de necessidade de coordenar fornecedores do cliente, este serviço não prevê este tipo de atividade, sendo de responsabilidade do cliente, coordenar e manter potenciais entregas e cronograma junto destes fornecedores ou empresas terceiras;\nO cliente reconhece que a conclusão dos serviços depende do cumprimento das entregas previstas nas premissas e da contratação de períodos de serviços adequados às dimensões e variedades do seu próprio ambiente;\nQuaisquer custos adicionais identificados como resultado do serviço prestado serão gerenciados através de gestões específicas. Como por exemplo: Gestão de Problemas e Gestão de Mudanças. Estes custos adicionais deverão ser tema de proposta comercial;\nOs serviços podem ser executados a critério da Selbetti pela Selbetti ou por indivíduos, contratados, fornecedores ou organizações empregadas ou contratadas sob contrato com a Selbetti;\nTodos os serviços serão fornecidos no idioma português, a menos que seja acordado de outra forma pelo cliente e pela Selbetti.'::text),'text','confirmado','Um item por linha',330)
ON CONFLICT (key) DO NOTHING;